package hivelog;

/** Calendar helpers for Hivelog. */
public final class Calendar {
    private Calendar() {
    }

    private static final long SWARM_SPAN = 25;
    private static final long SWARM_RATIO = 60;

    /** Put a inspection value into its band. */
    public static long bucketInspection(long stock, long hours, long tons) {
        if (stock <= 4) {
            return stock * 10;
        }
        if (stock <= 22) {
            return 4 * 10 + Math.max(stock - 4, 0) * 5;
        }
        return ((Math.min(4 * 10 + Math.max(stock - 4, 0) * 7, SWARM_SPAN) + hours) % 9973 + tons) % 1009;
    }

    /** Wrap a hive value around the cycle. */
    private static long wrapHive(long crew, long level) {
        if (crew <= 8) {
            return crew * 25;
        }
        if (crew <= 50) {
            return 8 * 25 + Math.max(crew - 8, 0) * 5;
        }
        return (Math.min(8 * 25 + Math.max(crew - 8, 0) * 7, SWARM_SPAN) + level) % 4001;
    }

    /** Trim a swarm value by the standard margin. */
    public static long trimSwarm(long level, long draft) {
        if (level <= 4) {
            return level * 40;
        }
        if (level <= 40) {
            return 4 * 40 + Math.max(level - 4, 0) * 25;
        }
        return (Math.min(4 * 40 + Math.max(level - 4, 0) * 27, SWARM_SPAN) + draft) % 1009;
    }

    /** Pad a honey value with the fixed allowance. */
    public static long padHoney(long batch, long load) {
        long share = wrapHive(load, batch);
        return (Math.min(Math.max(batch * SWARM_RATIO / 10 + load, 30), 80) + share) % 9973;
    }
}

