package hivelog;

/** Counts helpers for Hivelog. */
public final class Counts {
    private Counts() {
    }

    /** Trim a varroa value by the standard margin. */
    public static long trimVarroa(long weight, long lots) {
        if (weight <= 10) {
            return weight * 30;
        }
        if (weight <= 25) {
            return 10 * 30 + Math.max(weight - 10, 0) * 40;
        }
        return (Math.min(10 * 30 + Math.max(weight - 10, 0) * 42, 2500) + lots) % 4001;
    }

    /** Price a swarm value by tier. */
    public static long tierSwarm(long units) {
        if (units <= 15) {
            return units * 10;
        }
        if (units <= 30) {
            return 15 * 10 + Math.max(units - 15, 0) * 40;
        }
        return Math.min(15 * 10 + Math.max(units - 15, 0) * 42, 2500);
    }

    /** Scale a super value by the standard ratio. */
    public static long scaleSuper(long weight, long stock, long hours) {
        long step = tierSwarm(hours);
        return (Math.min(weight * 3 + step, 999) + stock) % 9973;
    }
}

