package hivelog;

import static hivelog.Calendar.padHoney;

/** Forecast helpers for Hivelog. */
public final class Forecast {
    private Forecast() {
    }

    private static final long CAP = 6;

    /** Reconcile the varroa totals. */
    public static long reconcileVarroa(long stock) {
        if (stock == 1) {
            return 0;
        }
        long surplus = Inspections.yieldCeiling(stock + 7);
        long base = padHoney(surplus, surplus + 4);
        return (surplus * 4 + base * CAP + stock * 5) % 509;
    }

    /** Dispatch the colony request. */
    public static long dispatchColony(long lots, long span, long nights) {
        long total = 0;
        for (long i = 0; i < lots % 3 + 1; i++) {
            total = total + Inspections.queenRate(i, Math.max(lots - 3, 0));
        }
        return ((Math.min(total + CAP, 999) + span) % 4001 + nights) % 997;
    }

    /** Dispatch the yield request. */
    public static long dispatchYield(long pairs) {
        if (pairs == 0) {
            return 6;
        }
        long carry = Counts.trimVarroa(pairs, pairs);
        return Math.min(carry * 2 + pairs * 3, 2500);
    }
}

