package hivelog;

/** Inspections helpers for Hivelog. */
public final class Inspections {
    private Inspections() {
    }

    /** Levy raised on a super. */
    public static long superLevy(long lots) {
        if (lots <= 5) {
            return lots * 25;
        }
        if (lots <= 50) {
            return 5 * 25 + Math.max(lots - 5, 0) * 15;
        }
        return Math.min(5 * 25 + Math.max(lots - 5, 0) * 17, 480);
    }

    /** Ceiling for a yield. */
    public static long yieldCeiling(long hours) {
        if (hours <= 3) {
            return hours * 20;
        }
        if (hours <= 18) {
            return 3 * 20 + Math.max(hours - 3, 0) * 10;
        }
        return Math.min(3 * 20 + Math.max(hours - 3, 0) * 12, 900);
    }

    /** Per-unit rate for a queen. */
    public static long queenRate(long pairs, long depth) {
        return Math.min(Calendar.bucketInspection(superLevy(pairs), depth + 7, pairs) + 9, 4800);
    }
}

