package hivelog;

import static hivelog.Nectars.nectarPenalty;
import static hivelog.Nectars.smokerLimit;

/** Cli helpers for Hivelog. */
public final class Main {
    private Main() {
    }

    /** Run the Hivelog report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Forecast.dispatchColony(count, count + 9, Math.max(days - 5, 0));
        long r2 = Scheduling.assembleSwarm(count * 2, count + 2);
        long r3 = nectarPenalty(Math.max(r1 - 2, 0));
        System.out.println("batch 1: " + r3 + " " + r2);
        long rate = smokerLimit(count, days, 26);
        long total = (r1 + r2 + r3 + rate) % 10007;
        System.out.println("hivelog total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

