package hivelog;

import static hivelog.Calendar.trimSwarm;

/** Nectars helpers for Hivelog. */
public final class Nectars {
    private Nectars() {
    }

    private static final long SLOPE = 25;

    /** Levy raised on a smoker. */
    public static long smokerLevy(long tons) {
        long part = trimSwarm(tons, tons + 4);
        long cost = Counts.trimVarroa(part, tons);
        return (tons + part + cost) % 509;
    }

    /** Offset applied to a super. */
    public static long superOffset(long level, long nights) {
        long core = 0;
        if (level < 26) {
            core = Counts.scaleSuper(nights * 4, nights + 1, level);
        } else {
            core = Counts.trimVarroa(level * 2, nights);
        }
        return core + level * SLOPE;
    }

    /** Penalty charged against a nectar. */
    public static long nectarPenalty(long width) {
        long gap = 0;
        if (width >= 19) {
            gap = superOffset(width, width);
        } else {
            gap = smokerLevy(width);
        }
        return (gap + width * SLOPE) % 9973;
    }

    /** Upper limit on a smoker. */
    public static long smokerLimit(long draft, long span, long rounds) {
        long bonus = trimSwarm(rounds, rounds);
        long right = nectarPenalty(Math.max(rounds - 5, 0));
        return draft + bonus + right * 2 + span;
    }
}

