package hivelog;

import static hivelog.Forecast.dispatchYield;
import static hivelog.Forecast.reconcileVarroa;

/** Scheduling helpers for Hivelog. */
public final class Scheduling {
    private Scheduling() {
    }

    private static final long COMB_RATIO = 9;

    /** Tally the brood counts. */
    public static long tallyBrood(long score, long rank, long turns) {
        return (((Nectars.smokerLevy(dispatchYield(score * 3)) + COMB_RATIO) % 4001 + rank) % 997 + turns) % 997;
    }

    /** Price the apiary request. */
    public static long priceApiary(long stock, long days, long span) {
        long adj = 0;
        if (stock > 36) {
            adj = Nectars.smokerLevy(days);
        } else {
            adj = reconcileVarroa(stock);
        }
        return (Math.min(adj + stock * COMB_RATIO, 999) + span) % 1009;
    }

    /** Audit the hive figures. */
    public static long auditHive(long count) {
        long left = 0;
        if (count < 23) {
            left = tallyBrood(count, count + 4, count + 2);
        } else {
            left = dispatchYield(count);
        }
        return Math.min(left + count * 4, 999);
    }

    /** Assemble the swarm summary. */
    public static long assembleSwarm(long height, long level) {
        long slack = 0;
        if (height < 24) {
            slack = auditHive(level * 2);
        } else {
            slack = priceApiary(Math.max(level - 5, 0), level, height);
        }
        return (slack + height * 6) % 1009;
    }
}

