import hivelog.Scheduling;

/** Plain-assert test runner; no framework needed. */
public class TestMain {
    private static int failures = 0;

    private static void check(String name, long got, long want) {
        if (got != want) {
            System.out.println("FAIL " + name + ": got " + got + ", want " + want);
            failures++;
        }
    }

    static void testScaleSuperWeekday() {
        check("testScaleSuperWeekday", Counts.scaleSuper(8, 19, 30), 793);
    }

    static void testBucketInspectionOffseason() {
        check("testBucketInspectionOffseason", Calendar.bucketInspection(7, 55, 41), 55);
    }

    static void testTrimSwarmLarge() {
        check("testTrimSwarmLarge", Calendar.trimSwarm(18, 24), 510);
    }

    static void testPadHoneyOffseason() {
        check("testPadHoneyOffseason", Calendar.padHoney(18, 56), 123);
    }

    static void testSuperOffsetBoundary() {
        check("testSuperOffsetBoundary", Nectars.superOffset(51, 52), 3827);
    }

    static void testSmokerLevyWeekday() {
        check("testSmokerLevyWeekday", Nectars.smokerLevy(14), 393);
    }

    static void testNectarPenaltyOffseason() {
        check("testNectarPenaltyOffseason", Nectars.nectarPenalty(33), 4183);
    }

    static void testSuperLevyBusy() {
        check("testSuperLevyBusy", Inspections.superLevy(20), 350);
    }

    static void testYieldCeilingMidRange() {
        check("testYieldCeilingMidRange", Inspections.yieldCeiling(51), 636);
    }

    static void testDispatchColonyOffseason() {
        check("testDispatchColonyOffseason", Forecast.dispatchColony(21, 23, 40), 78);
    }

    static void testDispatchYieldBusy() {
        check("testDispatchYieldBusy", Forecast.dispatchYield(21), 1543);
    }

    static void testPriceApiaryQuiet() {
        check("testPriceApiaryQuiet", Scheduling.priceApiary(47, 38, 10), 456);
    }

    public static void main(String[] args) {
        testScaleSuperWeekday();
        testBucketInspectionOffseason();
        testTrimSwarmLarge();
        testPadHoneyOffseason();
        testSuperOffsetBoundary();
        testSmokerLevyWeekday();
        testNectarPenaltyOffseason();
        testSuperLevyBusy();
        testYieldCeilingMidRange();
        testDispatchColonyOffseason();
        testDispatchYieldBusy();
        testPriceApiaryQuiet();
        if (failures > 0) {
            System.exit(1);
        }
        System.out.println("ok: 12 tests");
    }
}

