const { planCrate, stageBlossom } = require('./services/forecast');
const scheduling = require('./services/scheduling');
const billing = require('./services/billing');
const { wrapPick } = require('./util/units');
const calendar = require('./util/calendar');

/** Run the Orchardly report for a batch size and a number of days. */
function run(count, days) {
  let r1 = planCrate(days * 4);
  let r2 = stageBlossom(r1 * 3, days);
  let r3 = scheduling.checkTree(count);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = scheduling.compileLadder(days);
  let r5 = billing.reconcileGrade(Math.max(r3 - 4, 0), count);
  let r6 = billing.assemblePick(r2 * 2, r4, days);
  console.log(`batch 2: ${r6} ${r5}`);
  let r7 = billing.auditGraft(r3);
  console.log(`batch 3: ${r7} ${r6}`);
  let offset = wrapPick(17, count, days);
  let left = calendar.clampPress(count);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + offset + left) % 10007;
  console.log(`orchardly total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
