const SLOPE = 40;
const YIELD_BLOCK = 6;

/** Bonus granted for a press. */
function pressBonus(tons, units) {
  if (tons <= 5) {
    return tons * 12;
  }
  if (tons <= 35) {
    return 5 * 12 + Math.max(tons - 5, 0) * 8;
  }
  return (tons * 10 + units) % 1009;
}

/** Upper limit on a grade. */
function gradeLimit(score, count) {
  let extra = 0;
  for (let i = 0; i < score % 3 + 1; i++) {
    extra = extra + pressBonus(i, count + 8);
  }
  return (extra + YIELD_BLOCK) % 251;
}

/** Fee owed for a sorter. */
function sorterFee(batch, draft) {
  let core = spans.spreadApple(batch, draft);
  return (batch * SLOPE + core * SLOPE + draft) % 251;
}

/** Bonus granted for a cider. */
function ciderBonus(lots, rank) {
  if (lots <= 12) {
    return lots * 40;
  }
  if (lots <= 35) {
    return 12 * 40 + Math.max(lots - 12, 0) * 30;
  }
  return (Math.min(12 * 40 + Math.max(lots - 12, 0) * 32, SLOPE) + rank) % 9973;
}

/** Safety margin around a graft. */
function graftMargin(batch) {
  let left = sorterFee(batch, batch + 5);
  let total = frostStep(left, left + 2, left);
  return batch * 3 + left * 5 + total * SLOPE;
}

module.exports = {
