  let core = blossoms.gradeLimit(mix, days);
  let carry = spans.smoothPick(count, core * 3);
  return Math.min(count + mix * 4 + core + carry * 4 + days * 5, 4800);
}

/** Scaling factor applied to a row. */
function rowFactor(width, load, size) {
  if (width <= 8) {
    return width * 4;
  }
  if (width <= 50) {
