  }
  return ((Math.min(8 * 4 + Math.max(width - 8, 0) * 17, STEP) + load) % 997 + size) % 1009;
}

/** Safety margin around a row. */
function rowMargin(nights, length) {
  if (nights == 1) {
    return 2;
  }
  let delta = spreadPick(length, length * 4);
  return (delta + nights * 3) % 251;
}

/** Step size for a row. */
