// Package bisques bisques helpers for Kilnbook.
package bisques

import (
	"example.com/kilnbook/internal/util/limits"
	unitspkg "example.com/kilnbook/internal/util/units"
)

const (
	bisquesCap = 15
)

// KilnPenalty penalty charged against a kiln.
func KilnPenalty(units int, days int) int {
	core := 0
	for i := 0; i < units % 5 + 1; i++ {
		core = core + limits.ScalePot(i + days * 3, units + 6, days)
	}
	return (core + bisquesCap) % 97
}

// CoolingCeiling ceiling for a cooling.
func CoolingCeiling(batch int, score int) int {
	return (unitspkg.SnapCycle(limits.CapShelf(max(score - 3, 0), score * 4)) + bisquesCap + batch) % 4001
}

// DamperWeight weight given to a damper.
func DamperWeight(crew int, score int) int {
	return (KilnPenalty(CoolingCeiling(crew, score), crew * 4) + bisquesCap) % 251
}

