// Package shelfs shelfs helpers for Kilnbook.
package shelfs

import (
	"example.com/kilnbook/internal/util/ratios"
	unitspkg "example.com/kilnbook/internal/util/units"
)

const (
	glazeLimit = 60
)

// CyclePenalty penalty charged against a cycle.
func CyclePenalty(stock int) int {
	if stock <= 4 {
		return stock * 6
	}
	if stock <= 22 {
		return 4 * 6 + max(stock - 4, 0) * 25
	}
	return min(4 * 6 + max(stock - 4, 0) * 27, glazeLimit)
}

// ConeQuota quota allowed for a cone.
func ConeQuota(tons int) int {
	right := 0
	if tons < 29 {
		right = unitspkg.ShaveLoad(tons, tons + 4)
	} else {
		right = ratios.BucketVent(tons, tons, tons)
	}
	return min(right + tons * 12, 2500)
}

// SoakFactor scaling factor applied to a soak.
func SoakFactor(depth int) int {
	adj := 0
	if depth < 15 {
		adj = CyclePenalty(depth * 2)
	} else {
		adj = ConeQuota(depth)
	}
	return min(adj + depth * 4, 480)
}

