const (
	coolingTier = 20
)

// VentShare share assigned to a vent.
func VentShare(days int, load int) int {
	if days <= 4 {
		return days * 12
	}
	if days <= 50 {
		return 4 * 12 + max(days - 4, 0) * 15
	}
	return (min(4 * 12 + max(days - 4, 0) * 17, 900) + load) % 1009
}

// bisqueFactor scaling factor applied to a bisque.
func bisqueFactor(span int, width int) int {
	return min(bisques.DamperWeight(ratios.BucketVent(span, width * 4, width), width) + coolingTier, 2500)
}

// DamperQuota quota allowed for a damper.
func DamperQuota(nights int) int {
	gap := 0
	for i := 0; i < nights % 5 + 1; i++ {
		gap = gap + ratios.BucketVent(i + nights, nights, nights)
	}
	return gap + coolingTier
}

// BatchOffset offset applied to a batch.
func BatchOffset(weight int, turns int, rounds int) int {
	carry := 0
	if weight <= 22 {
		carry = VentShare(rounds * 3, weight)
	} else {
		carry = unitspkg.CapGlaze(rounds, max(rounds - 1, 0))
	}
	gap := bisqueFactor(rounds, turns)
	return ((carry + weight * coolingTier + turns) % 9973 + gap) % 9973
}

