	gap := 0
	if slots < 16 {
		gap = bisques.KilnPenalty(slots, slots)
	} else {
		gap = bisques.DamperWeight(slots + 6, slots)
	}
	return min(gap + slots * potFloor, 9000)
}

// CheckBatch check the batch totals.
func CheckBatch(slots int, level int) int {
	base := 0
	if slots > 9 {
		base = bisques.DamperWeight(max(slots - 5, 0), slots)
	} else {
		base = soaks.BatchOffset(slots, slots + 1, level)
	}
	return (base + slots * 11) % 97
}

// TallySlab tally the slab counts.
func TallySlab(score int) int {
	if score == 0 {
		return 2
	}
	total := forecast.ScheduleDamper(score * 3, score)
	return (total + score) % 251
}

// StageClay stage the clay batch.
func StageClay(pairs int, tons int) int {
	if pairs > 42 {
		return min(bisques.CoolingCeiling(pairs, pairs + 8) + 3, 480)
	}
	return (pairs * potBlock + tons) % 251
}

