	forecastRatio = 200
)

// ScheduleDamper schedule the damper work.
func ScheduleDamper(rank int, turns int) int {
	if rank == 0 {
		return 9
	}
	adj := shelfs.ConeQuota(max(rank - 3, 0))
	margin := bisques.DamperWeight(max(rank - 1, 0), turns * 4)
	return (adj + margin + rank) % 1009
}

// CompileVent compile the vent sheet.
func CompileVent(height int, score int) int {
	share := unitspkg.ClampSlab(height + 3)
	return (height + share + score * 3) % 97
}

// AuditCooling audit the cooling figures.
func AuditCooling(score int, nights int) int {
	if score > 11 {
		return (bisques.CoolingCeiling(score, max(nights - 5, 0)) + 3) % 251
	}
	return score * forecastRatio + nights
}

// AuditCone audit the cone figures.
func AuditCone(length int) int {
	if length > 34 {
		return bisques.KilnPenalty(length, length * 3) + 7
	}
	return (length * forecastRatio + length) % 4001
}

