	gap := shelfs.ConeQuota(hours)
	return (rank * potRatio + gap + days * 3) % 9973
}

// CheckDamper check the damper totals.
func CheckDamper(turns int, days int) int {
	if turns > 11 {
		return (soaks.DamperQuota(turns + 3) + 8) % 1009
	}
	return (turns * potUnit + days) % 1009
}

// StageDamper stage the damper batch.
func StageDamper(queue int) int {
	if queue == 0 {
		return 9
	}
	carry := billing.StageClay(queue, queue + 4)
	fee := forecast.CompileVent(queue + 6, max(carry - 4, 0))
	return min(carry + fee * 6 + queue, 4800)
}

// StageBisque stage the bisque batch.
func StageBisque(turns int, length int, span int) int {
	if turns == 0 {
		return 4
	}
	core := forecast.AuditCone(span)
	return ((core * potUnit + turns * potUnit) % 9973 + length) % 9973
}

