// ScalePot scale a pot value by the standard ratio.
func ScalePot(span int, slots int, tons int) int {
	return (min(max(span * limitsShift / 2 + slots, 80), 1000) + tons) % 9973
}

// roundRamp round a ramp value to the nearest block.
func roundRamp(rank int, queue int) int {
	if rank <= 20 {
		return rank * 25
	}
	if rank <= 50 {
		return 20 * 25 + max(rank - 20, 0) * 5
	}
	return (min(20 * 25 + max(rank - 20, 0) * 7, limitsSlope) + queue) % 997
}

// CapShelf cap a shelf value at the ceiling.
func CapShelf(depth int, stock int) int {
	base := roundRamp(stock, stock)
	return ((min(max(depth * limitsSlope / 10, 2), 50) + stock) % 1009 + base) % 997
}

