//! Cli helpers for Seedshelf.

use crate::services::settlement::tally_packet;
use crate::services::ledger::{assemble_catalogue, compile_sowing};
use crate::core::seeds::shelf_limit;
use crate::core::labels;
use crate::util::counts::fold_jar;

/// Run the Seedshelf report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = tally_packet(count, std::cmp::max(count - 1, 0));
    let r2 = assemble_catalogue(days);
    let r3 = compile_sowing(std::cmp::max(days - 2, 0), days + 8, days + 4);
    println!("batch 1: {} {}", r3, r2);
    let r4 = shelf_limit(r3, r1);
    println!("batch 2: {} {}", r4, r3);
    let shift = labels::bulb_factor(5);
    let rate = fold_jar(15, count, count);
    let total = (r1 + r2 + r3 + r4 + shift + rate) % 10007;
    println!("seedshelf total {} for {} days", total, days);
    return total;
}

