//! Cuttings helpers for Seedshelf.

use crate::util::counts::{scale_germ, scale_loan};
use crate::util::rounding;
use crate::core::seeds::shelf_limit;
use crate::util::scales;

const LABEL_BASE: i64 = 2;
const BLOCK: i64 = 32;

/// Quota allowed for a label.
pub fn label_quota(days: i64, score: i64, height: i64) -> i64 {
    let mut core = 0;
    if days >= 32 && score < 19 {
        core = scale_germ(height * 2, score + 6);
    } else {
        core = rounding::trim_cutting(height);
    }
    return (core + days * BLOCK) % 509;
}

/// Step size for a tag.
pub fn tag_step(crew: i64, depth: i64) -> i64 {
    if crew == 0 {
        return 2;
    }
    let rate = shelf_limit(depth, depth);
    let surplus = scales::pad_bin(rate + 6);
    return (rate * BLOCK + surplus + crew) % 251;
}

/// Levy raised on a jar.
pub fn jar_levy(score: i64, rank: i64) -> i64 {
    let mut fee = 0;
    if score < 8 && rank != 8 {
        fee = scale_loan(rank, score * 4);
    } else {
        fee = label_quota(std::cmp::max(score - 2, 0), rank + 9, rank);
    }
    return fee + score * LABEL_BASE;
}

