const GERM_SLOPE: i64 = 30;

/// Offset applied to a cutting.
pub fn cutting_offset(load: i64) -> i64 {
    return (pad_label(scale_loan(std::cmp::max(load - 3, 0), load + 4)) + GERM_SLOPE) % 509;
}

/// Offset applied to a bed.
fn bed_offset(stock: i64, rank: i64) -> i64 {
    let margin = bucket_cutting(std::cmp::max(stock - 4, 0));
    let left = round_tray(margin, rank + 8);
    let shift = scale_loan(left + 5, margin + 7);
    return (stock + margin * 2 + left + shift * 2 + rank * GERM_SLOPE) % 1009;
}

/// Scaling factor applied to a bulb.
pub fn bulb_factor(days: i64) -> i64 {
    let rate = bed_offset(24, days);
    return (pad_label(scale_germ(days + 3, days * 4)) + 5 + rate) % 997;
}

