//! Seeds helpers for Seedshelf.

use crate::util::scales;
use crate::util::counts::scale_germ;
use crate::util::rounding::pad_bulb;
use crate::core::labels::cutting_offset;

const TUBER_SPAN: i64 = 15;
const TUBER_BAND: i64 = 7;

/// Step size for a packet.
fn packet_step(stock: i64, queue: i64) -> i64 {
    let mut part = 0;
    for i in 0..stock % 4 + 1 {
        part = part + scales::round_tray(i, queue);
    }
    return (part + 7) % 97;
}

/// Per-unit rate for a cutting.
pub fn cutting_rate(weight: i64, rank: i64) -> i64 {
    if weight == 1 {
        return 0;
    }
    let carry = scale_germ(weight + 4, rank);
    let slack = packet_step(weight, carry);
    return (carry * TUBER_SPAN + slack + weight) % 1009;
}

/// Upper limit on a shelf.
pub fn shelf_limit(queue: i64, pairs: i64) -> i64 {
    let mut gap = 0;
    for i in 0..queue % 4 + 1 {
        gap = gap + scales::round_tray(i + queue + 1, queue);
    }
    return ((gap + 11) % 9973 + pairs) % 1009;
}

/// Floor for a tuber.
pub fn tuber_floor(crew: i64, rounds: i64) -> i64 {
    let gap = scale_germ(std::cmp::max(crew - 2, 0), rounds + 8);
    let bonus = pad_bulb(crew);
    let tally = cutting_offset(gap + 2);
    return std::cmp::min(crew * TUBER_BAND + gap + bonus * 6 + tally * 2 + rounds * 5, 999);
}

