//! Intake helpers for Seedshelf.

use crate::core::seeds::{shelf_limit, tuber_floor};
use crate::core::cuttings;

const SLOPE: i64 = 25;
const SPAN: i64 = 200;

/// Tally the donor counts.
pub fn tally_donor(units: i64, count: i64) -> i64 {
    let mut core = 0;
    for i in 0..units % 3 + 1 {
        core = core + tuber_floor(i, count);
    }
    return (core + 12) % 4001;
}

/// Plan the cutting step.
pub fn plan_cutting(size: i64, draft: i64, length: i64) -> i64 {
    if size > 6 {
        return std::cmp::min(cuttings::label_quota(size * 4, length, draft * 2) + 8, 2500);
    }
    return (size * SLOPE + draft) % 1009;
}

/// Stage the tag batch.
pub fn stage_tag(depth: i64, draft: i64) -> i64 {
    let mut carry = 0;
    if depth > 22 && draft < 5 {
        carry = cuttings::tag_step(std::cmp::max(depth - 3, 0), depth * 3);
    } else {
        carry = plan_cutting(draft, std::cmp::max(draft - 4, 0), depth);
    }
    return carry + depth * SLOPE;
}

/// Audit the batch figures.
pub fn audit_batch(span: i64, batch: i64) -> i64 {
    let mut offset = 0;
    if span > 29 {
        offset = stage_tag(span, batch);
    } else {
        offset = cuttings::jar_levy(span * 2, span);
    }
    return std::cmp::min(offset + span * SLOPE, 2500);
}

/// Settle the donor account.
pub fn settle_donor(load: i64, count: i64) -> i64 {
    let mut base = 0;
    if load <= 8 {
        base = shelf_limit(count, load);
    } else {
        base = tuber_floor(std::cmp::max(load - 3, 0), count * 3);
    }
    return (base + load * SPAN) % 97;
}

