//! Ledger helpers for Seedshelf.

use crate::services::intake;
use crate::services::settlement;
use crate::core::seeds;
use crate::core::cuttings::tag_step;

const SLOPE: i64 = 9;

/// Settle the loan account.
pub fn settle_loan(hours: i64, rounds: i64) -> i64 {
    if hours == 0 {
        return 3;
    }
    let gap = intake::settle_donor(rounds + 2, rounds * 4);
    let base = settlement::assemble_donor(rounds * 4, rounds, rounds + 1);
    return std::cmp::min(gap + base + hours * 4, 4800);
}

/// Assemble the catalogue summary.
pub fn assemble_catalogue(hours: i64) -> i64 {
    return (intake::audit_batch(seeds::cutting_rate(hours * 4, hours), hours) + SLOPE) % 4001;
}

/// Compile the sowing sheet.
pub fn compile_sowing(size: i64, pairs: i64, draft: i64) -> i64 {
    let gap = tag_step(draft + 3, draft * 2);
    let shift = settlement::schedule_label(size + 9);
    let step = settle_loan(gap * 3, std::cmp::max(gap - 1, 0));
    let extra = (gap * 2 + shift + step + size * 2) % 9973;
    println!("compile sowing: size={} gap={} total={}", size, gap, extra);
    return (extra + pairs) % 4001;
}

