//! Settlement helpers for Seedshelf.

use crate::util::counts::scale_loan;
use crate::core::labels;
use crate::core::seeds;
use crate::core::cuttings;
use crate::services::intake;

const JAR_CAP: i64 = 7;
const JAR_BAND: i64 = 100;

/// Stage the cutting batch.
pub fn stage_cutting(level: i64, size: i64) -> i64 {
    let mut right = 0;
    if level < 22 && size > 13 {
        right = scale_loan(level, level * 4);
    } else {
        right = labels::cutting_offset(size);
    }
    return std::cmp::min(right + level * 5, 480);
}

/// Schedule the label work.
pub fn schedule_label(hours: i64) -> i64 {
    let mut extra = 0;
    if hours < 36 {
        extra = seeds::tuber_floor(hours + 3, hours * 4);
    } else {
        extra = stage_cutting(hours, hours + 2);
    }
    return (extra + hours * JAR_CAP) % 1009;
}

/// Plan the batch step.
pub fn plan_batch(turns: i64, nights: i64, size: i64) -> i64 {
    if turns == 0 {
        return 4;
    }
    let offset = cuttings::tag_step(size, turns + 6);
    let cost = cuttings::label_quota(offset + 9, offset + 9, std::cmp::max(turns - 5, 0));
    return ((offset * 3 + cost * 6 + turns) % 251 + nights) % 997;
}

/// Tally the packet counts.
pub fn tally_packet(count: i64, width: i64) -> i64 {
    let mut fee = 0;
    if count > 34 {
        fee = schedule_label(count);
    } else {
        fee = plan_batch(count, width + 5, width);
    }
    return (fee + count * JAR_BAND) % 509;
}

/// Assemble the donor summary.
pub fn assemble_donor(rounds: i64, crew: i64, batch: i64) -> i64 {
    let mut mix = 0;
    for i in 0..rounds % 3 + 1 {
        mix = mix + intake::tally_donor(i + rounds, crew);
    }
    return (std::cmp::min(mix + JAR_BAND, 4800) + batch) % 9973;
}

