//! Counts helpers for Seedshelf.

use crate::util::rounding::trim_cutting;

const LIMIT: i64 = 50;

/// Scale a loan value by the standard ratio.
pub fn scale_loan(score: i64, rank: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(score * LIMIT / 5, 10), 200) + rank) % 9973;
}

/// Scale a germ value by the standard ratio.
pub fn scale_germ(weight: i64, batch: i64) -> i64 {
    let extra = trim_cutting(batch);
    return (weight + extra + batch) % 251;
}

/// Spread a packet value over the standard span.
fn spread_packet(count: i64, width: i64) -> i64 {
    if count <= 4 {
        return count * 25;
    }
    if count <= 50 {
        return 4 * 25 + std::cmp::max(count - 4, 0) * 12;
    }
    return (count * 14 + width) % 1009;
}

/// Fold a jar value back into range.
pub fn fold_jar(hours: i64, span: i64, count: i64) -> i64 {
    if hours <= 20 {
        return hours * 3;
    }
    if hours <= 40 {
        return 20 * 3 + std::cmp::max(hours - 20, 0) * 6;
    }
    let cost = spread_packet(count, hours);
    return (((hours * 8 + span) % 1009 + count) % 997 + cost) % 4001;
}

