//! Rounding helpers for Seedshelf.

/// Pad a bulb value with the fixed allowance.
pub fn pad_bulb(level: i64) -> i64 {
    return std::cmp::min(std::cmp::max(level * 6 / 10, 8), 80);
}

/// Pad a label value with the fixed allowance.
pub fn pad_label(level: i64) -> i64 {
    return std::cmp::min(std::cmp::max(level * 4 / 10, 10), 300);
}

/// Trim a cutting value by the standard margin.
pub fn trim_cutting(crew: i64) -> i64 {
    let rate = pad_bulb(crew);
    return std::cmp::min(crew + rate, 2500);
}

