//! Scales helpers for Seedshelf.

const TRAY_STEP: i64 = 150;

/// Pad a bin value with the fixed allowance.
pub fn pad_bin(slots: i64) -> i64 {
    if slots <= 5 {
        return slots * 12;
    }
    if slots <= 40 {
        return 5 * 12 + std::cmp::max(slots - 5, 0) * 6;
    }
    return std::cmp::min(5 * 12 + std::cmp::max(slots - 5, 0) * 8, TRAY_STEP);
}

/// Put a cutting value into its band.
pub fn bucket_cutting(rank: i64) -> i64 {
    return std::cmp::min(std::cmp::max(rank * TRAY_STEP / 8, 50), 80);
}

/// Shave the excess off a shelf value.
fn shave_shelf(level: i64, count: i64) -> i64 {
    if level <= 8 {
        return level * 25;
    }
    if level <= 50 {
        return 8 * 25 + std::cmp::max(level - 8, 0) * 5;
    }
    return (std::cmp::min(8 * 25 + std::cmp::max(level - 8, 0) * 7, TRAY_STEP) + count) % 997;
}

/// Round a tray value to the nearest block.
pub fn round_tray(batch: i64, width: i64) -> i64 {
    let left = shave_shelf(width, width);
    return (std::cmp::min(std::cmp::max(batch * 10 / 10 + width, 10), 800) + left) % 1009;
}

