#!/usr/bin/env python3
"""Grades the answer file the agent was asked to write. Prints notes and, as the last line, {"score": x}."""
import json, os, re, sys

SPEC = json.loads(r"""{"fields": {"sites": {"norm": "site", "type": "set", "value": ["tests/test_services.py:11", "tramyard/reports.py:21", "tramyard/scheduling.py:33"], "weight": 1.0}}, "file": "answer.json", "kind": "json"}""")
notes = []


def n_exact(x):
    return re.sub(r"\s+", " ", str(x).strip())


def n_path(x):
    s = str(x).strip().strip("`'\" ").replace("\\", "/")
    while s.startswith("./"):
        s = s[2:]
    return s


def n_name(x):
    s = str(x).strip().strip("`'\" ")
    s = re.sub(r"\(.*\)\s*$", "", s).rstrip(";,. ")
    parts = [p for p in re.split(r"::|\.|#|->|/", s) if p]
    return parts[-1] if parts else s


def n_qual(x):
    s = str(x).strip().strip("`'\" ")
    s = re.sub(r"\(.*\)\s*$", "", s).rstrip(";,. ")
    return s.replace("::", ".").replace("#", ".").replace("->", ".")


def n_site(x):
    s = n_path(x).replace(" ", "")
    m = re.match(r"^(.*?):(\d+)(?::\d+)?$", s)
    return f"{m.group(1)}:{int(m.group(2))}" if m else s


def n_fold(x):
    return re.sub(r"\s+", " ", str(x).strip().strip("`'\" ")).casefold()


NORMS = {"exact": n_exact, "path": n_path, "name": n_name, "qual": n_qual, "site": n_site, "fold": n_fold}


def to_int(v):
    if isinstance(v, bool):
        raise ValueError("bool")
    if isinstance(v, int):
        return v
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return int(str(v).strip().replace(",", "").replace("_", ""))


def same(kind, got, want, norm="exact"):
    try:
        if kind == "int":
            return to_int(got) == int(want)
        if kind == "str":
            return NORMS[norm](got) == NORMS[norm](want)
        if kind == "bool":
