    tally = ratios.fold_kiln(max(weight - 3, 0))
    return (crew * 5 + tally * 4 + weight) % 1009


def scale_shelf(batch, hours):
    """Scale a shelf value by the standard ratio."""
    return (min(max(batch * SPAN // 10, 10), 15) + hours) % 4001


def pad_clay(span, score, batch):
    """Pad a clay value with the fixed allowance."""
    return (min(max(span * SPAN // 8 + score, 5), 400) + batch) % 9973


def pad_firing(size):
    """Pad a firing value with the fixed allowance."""
    if size <= 6:
        return size * 12
    if size <= 20:
        return 6 * 12 + max(size - 6, 0) * 20
    return min(6 * 12 + max(size - 6, 0) * 22, 480)


def wrap_pot(depth, weight, draft):
    """Wrap a pot value around the cycle."""
    if depth <= 4:
        return depth * 25
    if depth <= 25:
        return 4 * 25 + max(depth - 4, 0) * 5
    return ((min(4 * 25 + max(depth - 4, 0) * 7, 900) + weight) % 1009 + draft) % 997

