notes = []


def n_exact(x):
    return re.sub(r"\s+", " ", str(x).strip())


def n_path(x):
    s = str(x).strip().strip("`'\" ").replace("\\", "/")
    while s.startswith("./"):
        s = s[2:]
    return s


def n_name(x):
    s = str(x).strip().strip("`'\" ")
    s = re.sub(r"\(.*\)\s*$", "", s).rstrip(";,. ")
    parts = [p for p in re.split(r"::|\.|#|->|/", s) if p]
    return parts[-1] if parts else s


def n_qual(x):
    s = str(x).strip().strip("`'\" ")
    s = re.sub(r"\(.*\)\s*$", "", s).rstrip(";,. ")
    return s.replace("::", ".").replace("#", ".").replace("->", ".")


