// Package booking booking helpers for Ropewalk.
package booking

import (
	"example.com/ropewalk/internal/intake"
	"example.com/ropewalk/internal/limits"
	"example.com/ropewalk/internal/steps"
	"example.com/ropewalk/internal/walks"
)

const (
	bookingCap = 12
	reelSpan = 60
)

// PriceMark price the mark request.
func PriceMark(weight int, queue int) int {
	gap := 0
	if weight <= 35 && queue != 8 {
		gap = walks.TarFactor(weight + 4, queue * 4)
	} else {
		gap = limits.TrimRope(queue * 3, queue)
	}
	step := limits.WrapHank(weight)
	return ((gap + weight * bookingCap) % 251 + step) % 4001
}

// PriceFibre price the fibre request.
func PriceFibre(turns int, tons int, height int) int {
	gap := 0
	for i := 0; i < turns % 5 + 1; i++ {
		gap = gap + steps.ClampMark(i + height)
	}
	return ((gap + reelSpan) % 9973 + tons) % 1009
}

// AuditHank audit the hank figures.
func AuditHank(load int, crew int) int {
	return min(intake.ReconcileMark(intake.DispatchCoil(crew, crew), load + 3) + 8, 2500)
}

