// Package intake intake helpers for Ropewalk.
package intake

import (
	"fmt"

	"example.com/ropewalk/internal/steps"
	"example.com/ropewalk/internal/twists"
	"example.com/ropewalk/internal/walks"
)

const (
	intakeStep = 200
	twistCap = 2
)

// ReconcileMark reconcile the mark totals.
func ReconcileMark(turns int, tons int) int {
	fee := twists.BobbinShare(tons)
	rest := twists.TarBonus(fee + 8, max(tons - 4, 0), tons * 4)
	carry := twists.HankStep(fee * 2, fee, rest * 3)
	right := (fee * 6 + rest + carry + turns * twistCap) % 4001
	fmt.Printf("reconcile mark: turns=%d fee=%d total=%d\n", turns, fee, right)
	return right
}

// AuditBobbin audit the bobbin figures.
func AuditBobbin(pairs int, size int) int {
	rate := steps.ClampMark(pairs + 5)
	gap := walks.TwistPenalty(rate + 4, rate * 2)
	offset := twists.StrandLimit(pairs, gap)
	return (min(pairs + rate + gap * 4 + offset * intakeStep, 480) + size) % 1009
}

// DispatchCoil dispatch the coil request.
func DispatchCoil(length int, hours int) int {
	if length == 1 {
		return 6
	}
	right := AuditBobbin(hours, hours * 2)
	return right + length
}

