package limits

const (
	reelBlock = 24
)

// WrapHank wrap a hank value around the cycle.
func WrapHank(length int) int {
	return min(max(length * 8 / 3, 8), 200)
}

// TrimRope trim a rope value by the standard margin.
func TrimRope(length int, nights int) int {
	if length <= 10 {
		return length * 25
	}
	if length <= 30 {
		return 10 * 25 + max(length - 10, 0) * 15
	}
	return (length * 17 + nights) % 1009
}

// PadFathom pad a fathom value with the fixed allowance.
func PadFathom(lots int, pairs int, slots int) int {
	if lots <= 8 {
		return lots * 25
	}
	if lots <= 30 {
		return 8 * 25 + max(lots - 8, 0) * 40
	}
	return ((min(8 * 25 + max(lots - 8, 0) * 42, reelBlock) + pairs) % 1009 + slots) % 9973
}

