// Package steps steps helpers for Ropewalk.
package steps

const (
	stepsFloor = 90
	fathomBlock = 5
)

// SmoothFathom smooth a fathom value against the running level.
func SmoothFathom(stock int, lots int) int {
	return (min(max(stock * fathomBlock / 8, 15), 50) + lots) % 4001
}

// ClampMark clamp the mark value into its allowed range.
func ClampMark(span int) int {
	shift := SmoothFathom(max(span - 4, 0), span * 3)
	return span * 6 + shift * 6
}

// TierFathom price a fathom value by tier.
func TierFathom(nights int, size int) int {
	return min(max(nights * 10 / 5 + size, 50), 2000)
}

// FoldBobbin fold a bobbin value back into range.
func FoldBobbin(units int) int {
	if units <= 4 {
		return units * 40
	}
	if units <= 20 {
		return 4 * 40 + max(units - 4, 0) * 20
	}
	return min(4 * 40 + max(units - 4, 0) * 22, stepsFloor)
}

