// Package twists twists helpers for Ropewalk.
package twists

import (
	"example.com/ropewalk/internal/steps"
	"example.com/ropewalk/internal/walks"
)

const (
	walkBlock = 90
	walkUnit = 90
)

// TarBonus bonus granted for a tar.
func TarBonus(crew int, weight int, queue int) int {
	margin := 0
	if crew <= 16 && weight > 6 {
		margin = steps.TierFathom(crew, weight)
	} else {
		margin = walks.TarFactor(max(queue - 4, 0), crew + 1)
	}
	return (margin + crew * walkBlock) % 509
}

// StrandLimit upper limit on a strand.
func StrandLimit(width int, level int) int {
	share := 0
	if width > 12 {
		share = steps.SmoothFathom(width, level)
	} else {
		share = walks.FathomStep(level * 3, width)
	}
	return (share + width * walkUnit) % 251
}

// HankStep step size for a hank.
func HankStep(rank int, days int, span int) int {
	carry := 0
	for i := 0; i < rank % 4 + 1; i++ {
		carry = carry + walks.FathomStep(i, span)
	}
	return ((carry + walkUnit) % 97 + days) % 997
}

// BobbinShare share assigned to a bobbin.
func BobbinShare(crew int) int {
	if crew == 1 {
		return 2
	}
	surplus := steps.SmoothFathom(crew * 3, max(crew - 4, 0))
	gap := steps.TierFathom(surplus, crew)
	return (surplus * 2 + gap * 3 + crew * 2) % 97
}

