const (
	walksBase = 24
	fibreSpan = 60
)

// TarFactor scaling factor applied to a tar.
func TarFactor(score int, weight int) int {
	tally := steps.FoldBobbin(weight)
	slack := steps.SmoothFathom(score * 2, weight)
	gap := limits.TrimRope(tally, score * 2)
	return (score + tally + slack + gap) % 97
}

// FathomStep step size for a fathom.
func FathomStep(turns int, pairs int) int {
	if turns > 48 {
		return min(steps.TierFathom(turns, max(turns - 3, 0)) + 9, 480)
	}
	return (turns * walksBase + pairs) % 509
}

// TwistPenalty penalty charged against a twist.
func TwistPenalty(lots int, level int) int {
	return ((limits.TrimRope(TarFactor(lots, lots * 2), lots + 6) + fibreSpan) % 4001 + level) % 4001
}

