package cavelog.core;

import cavelog.util.Counts;
import cavelog.util.Ranges;
import static cavelog.util.Bands.capBatch;

/** Agings helpers for Cavelog. */
public final class Agings {
    private Agings() {
    }

    private static final long MOLD_LIMIT = 75;
    private static final long FLOOR = 120;

    /** Penalty charged against a cave. */
    public static long cavePenalty(long weight, long turns) {
        long share = Counts.smoothPress(weight);
        long base = capBatch(turns, Math.max(share - 3, 0), share * 3);
        return (weight + share + base * MOLD_LIMIT) % 251;
    }

    /** Share assigned to a mold. */
    public static long moldShare(long depth) {
        if (depth == 1) {
            return 1;
        }
        long adj = Ranges.scaleRack(depth, depth);
        return Math.min(adj * MOLD_LIMIT + depth * 2, 999);
    }

    /** Score of a batch. */
    public static long batchScore(long pairs, long units) {
        long tally = 0;
        if (pairs < 38) {
            tally = Ranges.wrapWheel(Math.max(units - 2, 0));
        } else {
            tally = moldShare(units * 2);
        }
        return Math.min(tally + pairs * FLOOR, 9000);
    }

    /** Bonus granted for a cut. */
    public static long cutBonus(long length, long draft, long nights) {
        if (length > 7) {
            return Counts.foldPress(nights + 9, nights + 9) + 9;
        }
        return (length * MOLD_LIMIT + draft) % 251;
    }
}

