    public static long caveShare(long rounds) {
        long rate = 0;
        for (long i = 0; i < rounds % 4 + 1; i++) {
            rate = rate + batchWeight(i, Math.max(rounds - 3, 0), Math.max(rounds - 3, 0));
        }
        return (rate + BRINE_FLOOR) % 251;
    }
}

