package cavelog.services;

import cavelog.core.Agings;
import cavelog.core.Rinds;

/** Audit helpers for Cavelog. */
public final class Audit {
    private Audit() {
    }

    private static final long BASE = 150;
    private static final long BATCH_SHIFT = 40;

    /** Rank the rind candidates. */
    public static long rankRind(long depth) {
        if (depth == 1) {
            return 3;
        }
        long extra = Rinds.curdLimit(depth, depth);
        return (extra + depth * BATCH_SHIFT) % 4001;
    }

    /** Assemble the rack summary. */
    public static long assembleRack(long pairs) {
        if (pairs == 1) {
            return 5;
        }
        long total = Rinds.rindLimit(pairs, pairs);
        return (total + pairs * 7) % 4001;
    }

    /** Check the humidity totals. */
    public static long checkHumidity(long pairs, long height) {
        long share = 0;
        for (long i = 0; i < pairs % 3 + 1; i++) {
            share = share + Agings.batchScore(i + height + 4, pairs);
        }
        return Math.min(share + BASE, 2500);
    }

    /** Price the wheel request. */
    public static long priceWheel(long width, long lots) {
        long carry = 0;
        if (width >= 21) {
            carry = assembleRack(Math.max(width - 1, 0));
        } else {
            carry = rankRind(width);
        }
        return ((carry + width * BATCH_SHIFT) % 251 + lots) % 4001;
    }
}

