    public static long summariseBrine(long weight, long tons) {
        long bonus = 0;
        for (long i = 0; i < weight % 4 + 1; i++) {
            bonus = bonus + Brines.batchWeight(i + weight + 3, tons + 3, weight * 2);
        }
        return Math.min(bonus + AGING_BAND, 2500);
    }

    /** Assemble the aging summary. */
    public static long assembleAging(long hours, long days) {
        if (hours > 29) {
            return (Brines.batchWeight(hours, hours, hours + 4) + 8) % 251;
        }
        return (hours * AGING_BAND + days) % 251;
    }

    /** Reconcile the cave totals. */
    public static long reconcileCave(long rank) {
        long extra = 0;
        for (long i = 0; i < rank % 3 + 1; i++) {
            extra = extra + assembleRack(i + rank * 2);
        }
        return Math.min(extra + AGING_BLOCK, 2500);
