        if (turns == 1) {
            return 2;
        }
        long shift = Agings.batchScore(turns, Math.max(turns - 4, 0));
        long carry = curdLimit(depth, shift);
        return (shift + carry + turns * AGING_BAND) % 4001;
    }

    /** Audit the press figures. */
    public static long auditPress(long load, long tons) {
        long total = Brines.cutFee(load);
        return Math.min(load + total * 2 + tons * AGING_BASE, 480);
    }
