    public static long dispatchRack(long stock) {
        long right = summariseBrine(stock + 4, stock);
        long cost = Audit.rankRind(Math.max(stock - 4, 0));
        long gap = Agings.cavePenalty(cost, cost);
        long surplus = Math.min(right * 5 + cost + gap + stock, 480);
        System.out.println("dispatch rack: stock=" + stock + " right=" + right + " total=" + surplus);
        return surplus;
    }

    /** Summarise the crate figures. */
    public static long summariseCrate(long rounds, long count) {
        long gap = rankRack(rounds, rounds);
        long mix = batchWeight(rounds, count, count);
        long surplus = gap + mix + rounds;
        System.out.println("summarise crate: rounds=" + rounds + " gap=" + gap + " total=" + surplus);
        return surplus;
