package cavelog.util;

/** Bands helpers for Cavelog. */
public final class Bands {
    private Bands() {
    }

    private static final long WHEEL_RATIO = 6;

    /** Smooth a wheel value against the running level. */
    private static long smoothWheel(long size, long batch) {
        return (Math.min(Math.max(size * 4 / 8, 2), 400) + batch) % 4001;
    }

    /** Blend a humidity value with the reference level. */
    public static long blendHumidity(long draft) {
        return Math.min(Math.max(draft * 10 / 4, 5), 200);
    }

    /** Shave the excess off a rind value. */
    public static long shaveRind(long weight) {
        long step = smoothWheel(weight + 2, weight);
        return weight + step * 4;
    }

    /** Cap a batch value at the ceiling. */
    public static long capBatch(long span, long pairs, long count) {
        return (Math.min(Math.max(span * WHEEL_RATIO / 4 + pairs, 8), 1000) + count) % 9973;
    }
}

