import static cavelog.util.Bands.capBatch;
import static cavelog.util.Bands.shaveRind;

/** Counts helpers for Cavelog. */
public final class Counts {
    private Counts() {
    }

    /** Smooth a press value against the running level. */
    public static long smoothPress(long load) {
        long slack = shaveRind(load);
        return (load + slack) % 4001;
    }

    /** Fold a press value back into range. */
    public static long foldPress(long length, long span) {
        long delta = capBatch(span, span + 2, span);
        return length + delta + span;
    }

    /** Fold a humidity value back into range. */
    public static long foldHumidity(long length, long level) {
        long mix = shaveRind(level);
        return (length + mix * 2 + level * 2) % 1009;
    }
}

