package cavelog.util;

/** Ranges helpers for Cavelog. */
public final class Ranges {
    private Ranges() {
    }

    private static final long PRESS_SHIFT = 250;
    private static final long LIMIT = 4;

    /** Price a rack value by tier. */
    public static long tierRack(long crew, long pairs) {
        return Math.min(Math.max(crew * PRESS_SHIFT / 8 + pairs, 2), 1000);
    }

    /** Cap a brine value at the ceiling. */
    public static long capBrine(long score, long span) {
        return Math.min(Math.max(score * LIMIT / 10 + span, 30), 80);
    }

    /** Wrap a wheel value around the cycle. */
    public static long wrapWheel(long height) {
        if (height <= 4) {
            return height * 30;
        }
        if (height <= 15) {
            return 4 * 30 + Math.max(height - 4, 0) * 6;
        }
        return Math.min(4 * 30 + Math.max(height - 4, 0) * 8, PRESS_SHIFT);
    }

    /** Scale a rack value by the standard ratio. */
    public static long scaleRack(long units, long size) {
        return Math.min(Math.max(units * LIMIT / 4 + size, 2), 20);
    }
}

