//! Cli helpers for Hivelog.

use crate::services::reports::tally_feeder;
use crate::services::scheduling::{price_frame, settle_frame};
use crate::services::quotes::{rank_brood, schedule_super};
use crate::services::billing::{quote_hive, rank_queen, settle_inspection};
use crate::services::forecast;
use crate::services::audit::{audit_honey, price_smoker};
use crate::services::dispatch::assemble_colony;
use crate::core::colonies::brood_levy;
use crate::util::calendar::snap_inspection;

/// Run the Hivelog report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = tally_feeder(days);
    let r2 = settle_frame(r1, days, count);
    let r3 = price_frame(count + 9, days);
    println!("batch 1: {} {}", r3, r2);
    let r4 = rank_brood(r2, std::cmp::max(r2 - 4, 0), r1 + 9);
    let r5 = schedule_super(r1, days);
    let r6 = quote_hive(r3, r5);
    println!("batch 2: {} {}", r6, r5);
    let r7 = settle_inspection(r4, r2, days);
    let r8 = rank_queen(r4 + 9);
    let r9 = forecast::tally_queen(r1, std::cmp::max(r8 - 2, 0));
    println!("batch 3: {} {}", r9, r8);
    let r10 = forecast::settle_comb(r4, r6, r4 + 7);
    let r11 = forecast::schedule_apiary(std::cmp::max(r7 - 5, 0), days * 4, r6 * 2);
    let r12 = forecast::settle_colony(r7);
    println!("batch 4: {} {}", r12, r11);
    let r13 = audit_honey(r10 + 3);
    let r14 = price_smoker(days + 2, std::cmp::max(r11 - 2, 0));
    println!("batch 5: {} {}", r14, r13);
    let offset = assemble_colony(7);
    let core = brood_levy(count, 15);
    let margin = snap_inspection(27, days);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + offset + core + margin) % 10007;
    println!("hivelog total {} for {} days", total, days);
    return total;
}

