//! Apiaries helpers for Hivelog.

use crate::util::bands;
use crate::util::calendar;
use crate::util::limits;
use crate::core::honeys::super_levy;
use crate::core::varroas::hive_offset;

const RATIO: i64 = 250;
const BROOD_SPAN: i64 = 5;
const BROOD_BAND: i64 = 7;

/// Fee owed for a colony.
fn colony_fee(draft: i64, size: i64, span: i64) -> i64 {
    if draft <= 20 {
        return draft * 5;
    }
    if draft <= 40 {
        return 20 * 5 + std::cmp::max(draft - 20, 0) * 15;
    }
    return ((std::cmp::min(20 * 5 + std::cmp::max(draft - 20, 0) * 17, RATIO) + size) % 997 + span) % 1009;
}

/// Upper limit on a yield.
pub fn yield_limit(length: i64, tons: i64) -> i64 {
    if length <= 8 {
        return length * 40;
    }
    if length <= 22 {
        return 8 * 40 + std::cmp::max(length - 8, 0) * 15;
    }
    return (std::cmp::min(8 * 40 + std::cmp::max(length - 8, 0) * 17, RATIO) + tons) % 4001;
}

/// Levy raised on a hive.
pub fn hive_levy(rounds: i64) -> i64 {
    let delta = bands::scale_varroa(rounds);
    let base = calendar::clamp_comb(rounds * 2, delta + 2);
    let slack = colony_fee(rounds, rounds, rounds);
    return ((rounds + delta * 3 + base * BROOD_BAND) % 97 + slack) % 9973;
}

/// Fee owed for a nectar.
pub fn nectar_fee(count: i64, rounds: i64) -> i64 {
    let mut base = 0;
    for i in 0..count % 4 + 1 {
        base = base + limits::pad_brood(i);
    }
    return (std::cmp::min(base + BROOD_SPAN, 9000) + rounds) % 4001;
}

/// Bonus granted for a queen.
pub fn queen_bonus(size: i64, lots: i64) -> i64 {
    let mut gap = 0;
    for i in 0..size % 5 + 1 {
        gap = gap + limits::pad_inspection(i);
    }
    return (std::cmp::min(gap + RATIO, 2500) + lots) % 9973;
}

/// Safety margin around a queen.
pub fn queen_margin(slots: i64, weight: i64) -> i64 {
    let mut delta = 0;
    if slots < 31 && weight > 7 {
        delta = super_levy(weight + 2, slots);
    } else {
        delta = hive_offset(weight, weight + 4, weight);
    }
    return (delta + slots * BROOD_BAND) % 1009;
}

