//! Broods helpers for Hivelog.

use crate::util::ratios::{bucket_honey, clamp_smoker};
use crate::util::steps;
use crate::util::limits::trim_comb;

const HONEY_BLOCK: i64 = 150;

/// Quota allowed for a honey.
pub fn honey_quota(load: i64, count: i64) -> i64 {
    let tier = clamp_smoker(count);
    let fee = steps::wrap_comb(tier * 2, tier + 8, tier + 2);
    return (load + tier + fee) % 97;
}

/// Penalty charged against a smoker.
pub fn smoker_penalty(load: i64, level: i64, days: i64) -> i64 {
    let mut rate = 0;
    if load >= 12 {
        rate = bucket_honey(level, level);
    } else {
        rate = trim_comb(days + 3, days);
    }
    return std::cmp::min(rate + load * HONEY_BLOCK, 2500);
}

/// Floor for a hive.
pub fn hive_floor(draft: i64, height: i64) -> i64 {
    if draft <= 4 {
        return draft * 6;
    }
    if draft <= 30 {
        return 4 * 6 + std::cmp::max(draft - 4, 0) * 5;
    }
    return (std::cmp::min(4 * 6 + std::cmp::max(draft - 4, 0) * 7, 2500) + height) % 997;
}

/// Scaling factor applied to a colony.
pub fn colony_factor(length: i64, lots: i64) -> i64 {
    if length == 1 {
        return 4;
    }
    let bonus = steps::wrap_comb(length, std::cmp::max(length - 3, 0), length);
    return (bonus * 2 + length + lots) % 9973;
}

