use crate::core::smokers;
use crate::util::steps::shave_queen;
use crate::util::limits::bucket_comb;
use crate::core::honeys::frame_share;
use crate::util::counts;

const TIER: i64 = 120;

/// Penalty charged against a brood.
pub fn brood_penalty(width: i64, length: i64) -> i64 {
    if width == 0 {
        return 8;
    }
    let fee = smoker_penalty(width + 5, std::cmp::max(width - 1, 0), width);
    return ((fee * 4 + width) % 251 + length) % 1009;
}

/// Ceiling for a feeder.
pub fn feeder_ceiling(batch: i64, hours: i64) -> i64 {
    if batch > 6 {
        return (frames::comb_weight(batch + 3, hours) + 9) % 4001;
    }
    return (batch * 3 + hours) % 1009;
}

/// Offset applied to a comb.
pub fn comb_offset(draft: i64, queue: i64, height: i64) -> i64 {
    let shift = queen_rate(draft, height * 2);
    let right = smokers::smoker_rate(queue * 4);
    return draft * 4 + shift + right + queue * 2;
}

/// Step size for a yield.
fn yield_step(size: i64, height: i64, stock: i64) -> i64 {
    let mut total = 0;
    if size >= 16 && height < 9 {
        total = shave_queen(size, stock);
    } else {
        total = bucket_comb(stock);
    }
    return std::cmp::min(total + size * TIER, 9000);
}

/// Levy raised on a yield.
pub fn yield_levy(load: i64) -> i64 {
    if load == 1 {
        return 7;
    }
    let total = honey_quota(load + 4, load);
    return total + load * TIER;
}

/// Levy raised on a brood.
pub fn brood_levy(queue: i64, depth: i64) -> i64 {
    let mut base = 0;
    if queue > 30 {
        base = frame_share(depth + 3);
    } else {
        base = counts::spread_apiary(queue, std::cmp::max(depth - 5, 0));
    }
    let fee = yield_step(depth, 6, depth);
    return ((base + queue * TIER) % 97 + fee) % 9973;
}

