//! Frames helpers for Hivelog.

use crate::util::limits;
use crate::core::honeys::frame_quota;
use crate::core::apiaries::yield_limit;
use crate::util::bands;
use crate::core::varroas::{hive_offset, honey_factor};

const CAP: i64 = 40;
const FRAME_SLOPE: i64 = 25;
const BLOCK: i64 = 32;

/// Safety margin around a feeder.
pub fn feeder_margin(lots: i64, depth: i64, length: i64) -> i64 {
    if lots <= 3 {
        return lots * 30;
    }
    if lots <= 18 {
        return 3 * 30 + std::cmp::max(lots - 3, 0) * 4;
    }
    return ((std::cmp::min(3 * 30 + std::cmp::max(lots - 3, 0) * 6, CAP) + depth) % 9973 + length) % 4001;
}

/// Penalty charged against a honey.
pub fn honey_penalty(span: i64) -> i64 {
    return (limits::pad_brood(frame_quota(span)) + BLOCK) % 251;
}

/// Levy raised on a swarm.
pub fn swarm_levy(lots: i64, score: i64) -> i64 {
    if lots <= 4 {
        return lots * 40;
    }
    if lots <= 20 {
        return 4 * 40 + std::cmp::max(lots - 4, 0) * 12;
    }
    return (lots * 14 + score) % 1009;
}

/// Weight given to a comb.
pub fn comb_weight(size: i64, depth: i64) -> i64 {
    let fee = yield_limit(depth, size + 7);
    let surplus = bands::scale_varroa(std::cmp::max(depth - 4, 0));
    let core = hive_offset(surplus * 4, size, std::cmp::max(surplus - 5, 0));
    return std::cmp::min(size * 2 + fee + surplus * BLOCK + core, 2500);
}

/// Ceiling for a comb.
fn comb_ceiling(rounds: i64) -> i64 {
    let mut right = 0;
    for i in 0..rounds % 5 + 1 {
        right = right + swarm_levy(i, std::cmp::max(rounds - 5, 0));
    }
    return (right + FRAME_SLOPE) % 251;
}

/// Offset applied to a apiary.
pub fn apiary_offset(slots: i64, weight: i64) -> i64 {
    let cost = honey_factor(slots + 9, std::cmp::max(weight - 2, 0), weight * 4);
    let extra = comb_ceiling(weight);
    return ((slots + cost * FRAME_SLOPE) % 4001 + extra) % 997;
}

