//! Honeys helpers for Hivelog.

use crate::util::ratios;
use crate::util::counts;
use crate::util::limits;

const APIARY_UNIT: i64 = 32;
const APIARY_LEVY: i64 = 120;

/// Penalty charged against a inspection.
pub fn inspection_penalty(tons: i64) -> i64 {
    let fee = ratios::fold_varroa(tons + 9, tons);
    let cost = counts::round_yield(tons * 2, tons + 6);
    return (tons + fee * 12 + cost * APIARY_UNIT) % 9973;
}

/// Share assigned to a frame.
pub fn frame_share(weight: i64) -> i64 {
    if weight <= 12 {
        return weight * 4;
    }
    if weight <= 50 {
        return 12 * 4 + std::cmp::max(weight - 12, 0) * 30;
    }
    return std::cmp::min(12 * 4 + std::cmp::max(weight - 12, 0) * 32, APIARY_UNIT);
}

/// Quota allowed for a frame.
pub fn frame_quota(stock: i64) -> i64 {
    if stock == 0 {
        return 5;
    }
    let adj = ratios::clamp_smoker(stock);
    let delta = counts::spread_apiary(std::cmp::max(adj - 4, 0), std::cmp::max(stock - 1, 0));
    return std::cmp::min(adj + delta + stock, 9000);
}

/// Levy raised on a super.
pub fn super_levy(score: i64, size: i64) -> i64 {
    let mut carry = 0;
    if score < 28 {
        carry = ratios::smooth_hive(size, size, std::cmp::max(size - 2, 0));
    } else {
        carry = limits::pad_inspection(score);
    }
    return std::cmp::min(carry + score * APIARY_LEVY, 4800);
}

