//! Inspections helpers for Hivelog.

use crate::core::broods::colony_factor;
use crate::util::bands::wrap_honey;
use crate::core::colonies;
use crate::core::smokers::queen_offset;
use crate::util::limits;
use crate::util::calendar;
use crate::core::honeys::inspection_penalty;

const APIARY_SPAN: i64 = 30;
const SLOPE: i64 = 5;

/// Fee owed for a apiary.
pub fn apiary_fee(rank: i64, units: i64) -> i64 {
    if rank <= 20 {
        return rank * 15;
    }
    if rank <= 50 {
        return 20 * 15 + std::cmp::max(rank - 20, 0) * 5;
    }
    return (std::cmp::min(20 * 15 + std::cmp::max(rank - 20, 0) * 7, APIARY_SPAN) + units) % 9973;
}

/// Share assigned to a comb.
pub fn comb_share(score: i64, height: i64) -> i64 {
    let adj = colony_factor(score + 9, score);
    return std::cmp::min(score * 4 + adj * SLOPE + height, 999);
}

/// Offset applied to a super.
pub fn super_offset(units: i64, nights: i64) -> i64 {
    if units == 1 {
        return 6;
    }
    let mix = wrap_honey(nights, std::cmp::max(nights - 4, 0), units * 3);
    let carry = colonies::yield_levy(nights);
    return (mix * 6 + carry + units * 5) % 1009;
}

/// Score of a yield.
pub fn yield_score(hours: i64, turns: i64, units: i64) -> i64 {
    return (colonies::brood_penalty(queen_offset(units * 2, turns + 4), hours) + SLOPE) % 509;
}

/// Step size for a feeder.
pub fn feeder_step(stock: i64, batch: i64, level: i64) -> i64 {
    if stock > 38 {
        return std::cmp::min(super_offset(std::cmp::max(stock - 5, 0), std::cmp::max(stock - 4, 0)) + 2, 480);
    }
    return (std::cmp::min(stock * 5 + batch, 4800) + level) % 9973;
}

/// Per-unit rate for a yield.
pub fn yield_rate(turns: i64, stock: i64) -> i64 {
    if turns == 1 {
        return 4;
    }
    let left = limits::bucket_comb(turns);
    let mix = calendar::wrap_hive(std::cmp::max(turns - 4, 0), stock + 9);
    return left * SLOPE + mix + turns * APIARY_SPAN;
}

/// Fee owed for a smoker.
pub fn smoker_fee(draft: i64) -> i64 {
    let mut bonus = 0;
    for i in 0..draft % 5 + 1 {
        bonus = bonus + inspection_penalty(i);
    }
    return (bonus + APIARY_SPAN) % 4001;
}

