//! Smokers helpers for Hivelog.

use crate::core::swarms;
use crate::util::bands;
use crate::util::calendar::{snap_super, wrap_hive};
use crate::util::ratios::clamp_smoker;
use crate::util::counts::spread_apiary;

const SPAN: i64 = 12;
const BLOCK: i64 = 6;

/// Scaling factor applied to a frame.
pub fn frame_factor(draft: i64) -> i64 {
    let mut part = 0;
    for i in 0..draft % 5 + 1 {
        part = part + swarms::smoker_ceiling(i, draft);
    }
    return std::cmp::min(part + SPAN, 9000);
}

/// Scaling factor applied to a super.
pub fn super_factor(turns: i64) -> i64 {
    return std::cmp::min(bands::spread_swarm(snap_super(turns, turns * 3), turns * 2) + BLOCK, 999);
}

/// Per-unit rate for a smoker.
pub fn smoker_rate(slots: i64) -> i64 {
    let mut tally = 0;
    if slots < 8 {
        tally = clamp_smoker(slots);
    } else {
        tally = wrap_hive(std::cmp::max(slots - 3, 0), slots * 3);
    }
    return std::cmp::min(tally + slots * 6, 999);
}

/// Offset applied to a queen.
pub fn queen_offset(tons: i64, span: i64) -> i64 {
    let slack = bands::blend_nectar(span);
    return (tons * 4 + slack + span * SPAN) % 509;
}

/// Step size for a inspection.
pub fn inspection_step(units: i64, depth: i64) -> i64 {
    let bonus = spread_apiary(units, depth * 3);
    return std::cmp::min(units + bonus + depth, 2500);
}

