//! Swarms helpers for Hivelog.

use crate::util::calendar::{clamp_comb, spread_inspection};
use crate::util::ratios::clamp_smoker;
use crate::util::limits::bucket_comb;
use crate::util::bands::{scale_varroa, trim_super};
use crate::util::counts;

const INSPECTION_RATIO: i64 = 20;
const FLOOR: i64 = 64;

/// Upper limit on a inspection.
fn inspection_limit(level: i64) -> i64 {
    let mut part = 0;
    if level > 3 {
        part = spread_inspection(level * 3);
    } else {
        part = clamp_smoker(level);
    }
    return (part + level * FLOOR) % 251;
}

/// Levy raised on a feeder.
pub fn feeder_levy(level: i64, stock: i64, width: i64) -> i64 {
    let mut rest = 0;
    if level > 17 {
        rest = clamp_comb(level, std::cmp::max(width - 1, 0));
    } else {
        rest = bucket_comb(std::cmp::max(width - 2, 0));
    }
    return ((rest + level * INSPECTION_RATIO) % 97 + stock) % 4001;
}

/// Ceiling for a smoker.
pub fn smoker_ceiling(batch: i64, weight: i64) -> i64 {
    let mut extra = 0;
    for i in 0..batch % 4 + 1 {
        extra = extra + trim_super(i, weight);
    }
    let step = inspection_limit(22);
    return (std::cmp::min(extra + 7, 999) + step) % 1009;
}

/// Upper limit on a frame.
pub fn frame_limit(size: i64, level: i64, height: i64) -> i64 {
    if size == 1 {
        return 8;
    }
    let core = scale_varroa(height);
    let rest = counts::smooth_feeder(std::cmp::max(core - 2, 0), level * 3);
    return core + rest * 3 + size * 2;
}

