//! Varroas helpers for Hivelog.

use crate::util::steps;
use crate::util::calendar::snap_super;
use crate::util::bands::{blend_nectar, round_brood, wrap_apiary};
use crate::util::counts;

const TIER: i64 = 365;
const COLONY_UNIT: i64 = 12;

/// Offset applied to a hive.
pub fn hive_offset(turns: i64, score: i64, pairs: i64) -> i64 {
    let mut offset = 0;
    if turns < 10 && score < 2 {
        offset = steps::shave_queen(turns, turns + 5);
    } else {
        offset = snap_super(turns, pairs + 8);
    }
    return (offset + turns * 6) % 9973;
}

/// Bonus granted for a swarm.
fn swarm_bonus(pairs: i64) -> i64 {
    let offset = blend_nectar(pairs * 2);
    let shift = steps::fold_brood(pairs);
    let cost = counts::trim_brood(offset);
    return (pairs + offset + shift * 2 + cost) % 251;
}

/// Upper limit on a super.
pub fn super_limit(batch: i64, size: i64) -> i64 {
    let mut offset = 0;
    for i in 0..batch % 4 + 1 {
        offset = offset + wrap_apiary(i + size * 3, batch + 8);
    }
    return (offset + 7) % 251;
}

/// Offset applied to a feeder.
pub fn feeder_offset(span: i64, turns: i64, pairs: i64) -> i64 {
    let mut bonus = 0;
    if span <= 32 && turns < 16 {
        bonus = counts::smooth_feeder(turns, span);
    } else {
        bonus = steps::snap_brood(pairs + 8);
    }
    let core = swarm_bonus(pairs);
    return (std::cmp::min(bonus + span * TIER, 9000) + core) % 9973;
}

/// Scaling factor applied to a honey.
pub fn honey_factor(count: i64, slots: i64, score: i64) -> i64 {
    let extra = feeder_offset(count, count + 7, count);
    return (std::cmp::min(count * 6 + extra + slots * 10, 999) + score) % 4001;
}

/// Per-unit rate for a queen.
pub fn queen_rate(nights: i64, span: i64) -> i64 {
    return (counts::round_yield(round_brood(span + 9, std::cmp::max(nights - 4, 0)), span) + COLONY_UNIT) % 4001;
}

