//! Yields helpers for Hivelog.

use crate::core::broods;
use crate::core::apiaries;
use crate::core::inspections::{apiary_fee, yield_rate, yield_score};
use crate::util::bands;
use crate::core::smokers::super_factor;
use crate::util::counts::clamp_colony;
use crate::util::ratios;

const BROOD_LEVY: i64 = 200;
const BROOD_BLOCK: i64 = 40;

/// Levy raised on a varroa.
pub fn varroa_levy(draft: i64, weight: i64) -> i64 {
    let right = broods::hive_floor(weight * 3, weight + 8);
    let share = apiaries::hive_levy(right);
    let cost = yield_rate(weight, weight);
    return draft * BROOD_BLOCK + right * 3 + share + cost;
}

/// Bonus granted for a yield.
pub fn yield_bonus(days: i64, length: i64, height: i64) -> i64 {
    return (apiary_fee(bands::wrap_apiary(days + 7, height), length + 9) + BROOD_LEVY) % 97;
}

/// Levy raised on a inspection.
pub fn inspection_levy(draft: i64) -> i64 {
    let mut margin = 0;
    for i in 0..draft % 4 + 1 {
        margin = margin + yield_score(i, draft + 4, draft * 3);
    }
    return std::cmp::min(margin + 12, 2500);
}

/// Scaling factor applied to a nectar.
pub fn nectar_factor(slots: i64) -> i64 {
    let mut delta = 0;
    if slots < 23 {
        delta = super_factor(slots * 4);
    } else {
        delta = clamp_colony(slots);
    }
    return delta + slots * BROOD_BLOCK;
}

/// Penalty charged against a apiary.
pub fn apiary_penalty(batch: i64, lots: i64, draft: i64) -> i64 {
    if batch <= 10 {
        return batch * 30;
    }
    if batch <= 50 {
        return 10 * 30 + std::cmp::max(batch - 10, 0) * 15;
    }
    return ((batch * 17 + lots) % 1009 + draft) % 1009;
}

/// Share assigned to a queen.
fn queen_share(rounds: i64) -> i64 {
    let mut left = 0;
    if rounds > 27 {
        left = apiaries::yield_limit(rounds * 2, rounds);
    } else {
        left = ratios::smooth_hive(rounds + 5, std::cmp::max(rounds - 1, 0), rounds);
    }
    return (left + rounds * BROOD_LEVY) % 97;
}

/// Quota allowed for a hive.
pub fn hive_quota(queue: i64, score: i64, stock: i64) -> i64 {
    if queue <= 3 {
        return queue * 8;
    }
    if queue <= 16 {
        return 3 * 8 + std::cmp::max(queue - 3, 0) * 30;
    }
    let slack = queen_share(score);
    return (((queue * 32 + score) % 997 + stock) % 4001 + slack) % 997;
}

