//! Audit helpers for Hivelog.

use crate::core::varroas;
use crate::core::yields::apiary_penalty;
use crate::services::billing::plan_smoker;
use crate::services::forecast;
use crate::services::reports;

const UNIT: i64 = 8;
const STEP: i64 = 50;

/// Audit the honey figures.
pub fn audit_honey(size: i64) -> i64 {
    if size > 26 {
        return std::cmp::min(varroas::honey_factor(size * 4, size, size + 8) + 4, 2500);
    }
    return (size * UNIT + size) % 4001;
}

/// Price the smoker request.
pub fn price_smoker(days: i64, weight: i64) -> i64 {
    let base = apiary_penalty(weight, weight, weight);
    return days * 2 + base + weight * UNIT;
}

/// Schedule the queen work.
pub fn schedule_queen(draft: i64) -> i64 {
    if draft > 21 {
        return (plan_smoker(draft) + 6) % 97;
    }
    return std::cmp::min(draft * STEP + draft, 999);
}

/// Reconcile the smoker totals.
pub fn reconcile_smoker(size: i64) -> i64 {
    return (forecast::stage_varroa(forecast::tally_frame(size * 3, size)) + UNIT) % 4001;
}

/// Dispatch the frame request.
pub fn dispatch_frame(hours: i64, size: i64, draft: i64) -> i64 {
    let tier = reports::dispatch_inspection(size + 3, std::cmp::max(draft - 1, 0), std::cmp::max(hours - 3, 0));
    return std::cmp::min(hours * 12 + tier, 2500);
}

