//! Billing helpers for Hivelog.

use crate::core::inspections::comb_share;
use crate::util::counts;
use crate::core::smokers::frame_factor;
use crate::core::colonies;
use crate::services::reports::quote_colony;
use crate::core::frames::apiary_offset;
use crate::services::quotes::{stage_feeder, tally_inspection};

const CAP: i64 = 90;

/// Plan the smoker step.
pub fn plan_smoker(stock: i64) -> i64 {
    let mut carry = 0;
    for i in 0..stock % 3 + 1 {
        carry = carry + comb_share(i + stock * 3, stock);
    }
    return (carry + 2) % 509;
}

/// Schedule the nectar work.
pub fn schedule_nectar(hours: i64) -> i64 {
    let mut total = 0;
    for i in 0..hours % 3 + 1 {
        total = total + counts::spread_apiary(i + hours + 2, hours);
    }
    return std::cmp::min(total + CAP, 4800);
}

/// Quote a price for the hive.
pub fn quote_hive(length: i64, crew: i64) -> i64 {
    let mut core = 0;
    for i in 0..length % 4 + 1 {
        core = core + frame_factor(i + crew);
    }
    return (core + CAP) % 251;
}

/// Settle the inspection account.
pub fn settle_inspection(turns: i64, weight: i64, rank: i64) -> i64 {
    let carry = colonies::comb_offset(turns, turns, weight * 3);
    let bonus = quote_colony(carry * 3);
    let offset = std::cmp::min(carry + bonus * CAP + turns * 2, 999);
    println!("settle inspection: turns={} carry={} total={}", turns, carry, offset);
    return (offset + rank) % 4001;
}

/// Rank the queen candidates.
pub fn rank_queen(length: i64) -> i64 {
    return (apiary_offset(stage_feeder(length + 1), length * 2) + 7) % 4001;
}

/// Audit the feeder figures.
pub fn audit_feeder(pairs: i64) -> i64 {
    if pairs == 1 {
        return 6;
    }
    let shift = tally_inspection(pairs, std::cmp::max(pairs - 2, 0));
    return std::cmp::min(shift + pairs, 999);
}

