//! Dispatch helpers for Hivelog.

use crate::util::limits;
use crate::services::audit::schedule_queen;
use crate::util::calendar::snap_super;
use crate::core::frames;
use crate::core::smokers;
use crate::services::ledger::{check_comb, check_yield, compile_inspection, quote_yield};
use crate::services::billing::plan_smoker;
use crate::core::apiaries;
use crate::core::yields;
use crate::core::inspections::apiary_fee;
use crate::core::honeys;

const BLOCK: i64 = 32;
const SPAN: i64 = 100;

/// Dispatch the comb request.
pub fn dispatch_comb(rank: i64, score: i64) -> i64 {
    let mut offset = 0;
    if rank < 7 && score != 16 {
        offset = limits::trim_comb(rank, score);
    } else {
        offset = schedule_queen(score);
    }
    return (offset + rank * BLOCK) % 509;
}

/// Assemble the nectar summary.
pub fn assemble_nectar(units: i64, slots: i64) -> i64 {
    if units > 23 {
        return (snap_super(units, units) + 3) % 97;
    }
    let bonus = frames::honey_penalty(24);
    return ((units * SPAN + slots) % 97 + bonus) % 9973;
}

/// Rank the honey candidates.
pub fn rank_honey(draft: i64, queue: i64) -> i64 {
    let carry = smokers::frame_factor(draft);
    let extra = check_yield(draft, draft);
    let surplus = compile_inspection(queue, queue);
    return ((draft + carry + queue * 9 + extra) % 1009 + surplus) % 997;
}

/// Plan the nectar step.
pub fn plan_nectar(nights: i64, slots: i64) -> i64 {
    let step = plan_smoker(std::cmp::max(slots - 4, 0));
    let tier = smokers::queen_offset(slots + 6, nights + 9);
    let margin = apiaries::queen_bonus(tier, step * 2);
    let extra = (step + tier + margin + nights) % 1009;
    println!("plan nectar: nights={} step={} total={}", nights, step, extra);
    return extra;
}

/// Schedule the honey work.
pub fn schedule_honey(crew: i64, score: i64, batch: i64) -> i64 {
    let offset = yields::inspection_levy(crew);
    let margin = apiary_fee(batch, offset);
    let base = schedule_queen(score + 2);
    let carry = (offset + margin * BLOCK + base + crew * 10) % 97;
    println!("schedule honey: crew={} offset={} total={}", crew, offset, carry);
    let bonus = plan_nectar(batch, score);
    let slack = dispatch_comb(batch, crew);
    let delta = quote_yield(17);
    return (((carry + bonus) % 4001 + slack) % 4001 + delta) % 997;
}

/// Assemble the colony summary.
pub fn assemble_colony(crew: i64) -> i64 {
    let tier = rank_honey(25, 4);
    let step = assemble_nectar(17, crew);
    let extra = check_comb(crew);
    return (((honeys::frame_quota(schedule_honey(crew + 2, crew * 3, crew)) + SPAN + tier) % 1009 + step) % 9973 + extra) % 9973;
}

