const SPAN: i64 = 365;
const UNIT: i64 = 64;
const BAND: i64 = 120;

/// Tally the queen counts.
pub fn tally_queen(draft: i64, batch: i64) -> i64 {
    let mut part = 0;
    for i in 0..draft % 5 + 1 {
        part = part + apiaries::nectar_fee(i, batch);
    }
    return part + 3;
}

/// Compile the queen sheet.
pub fn compile_queen(hours: i64) -> i64 {
    return feeder_margin(colonies::brood_penalty(hours, hours + 5), hours + 9, hours * 2) + UNIT;
}

/// Settle the comb account.
pub fn settle_comb(nights: i64, tons: i64, crew: i64) -> i64 {
    let margin = inspections::yield_score(crew, crew + 8, tons * 3);
    let base = steps::wrap_comb(margin, tons + 1, margin * 3);
    let mix = feeder_levy(nights, margin * 3, std::cmp::max(tons - 3, 0));
    let tally = std::cmp::min(margin + base + mix * BAND + nights, 480);
    println!("settle comb: nights={} margin={} total={}", nights, margin, tally);
    return tally;
}

/// Stage the varroa batch.
pub fn stage_varroa(hours: i64) -> i64 {
    if hours > 46 {
        return std::cmp::min(feeder_margin(std::cmp::max(hours - 4, 0), hours + 2, hours * 3) + 4, 480);
    }
    return (hours * BAND + hours) % 4001;
}

/// Tally the frame counts.
pub fn tally_frame(queue: i64, tons: i64) -> i64 {
    let mut part = 0;
    if queue > 30 {
        part = inspection_step(std::cmp::max(tons - 1, 0), std::cmp::max(tons - 4, 0));
    } else {
        part = colony_factor(queue, tons);
    }
    return std::cmp::min(part + queue * 6, 2500);
}

/// Schedule the apiary work.
pub fn schedule_apiary(turns: i64, rounds: i64, weight: i64) -> i64 {
    let core = billing::schedule_nectar(weight + 4);
    let gap = billing::audit_feeder(rounds);
    let left = std::cmp::min(core * BAND + gap * SPAN + turns * 5, 999);
    println!("schedule apiary: turns={} core={} total={}", turns, core, left);
    return left;
}

/// Settle the colony account.
pub fn settle_colony(rank: i64) -> i64 {
    if rank == 1 {
        return 5;
    }
    let cost = yields::inspection_levy(rank + 4);
    return (cost + rank * 5) % 1009;
}

