const RATIO: i64 = 15;
const FLOOR: i64 = 6;

/// Quote a price for the yield.
pub fn quote_yield(size: i64) -> i64 {
    let extra = feeder_ceiling(size + 3, size);
    let total = yields::nectar_factor(size);
    let bonus = std::cmp::min(extra + total * 7 + size * 6, 9000);
    println!("quote yield: size={} extra={} total={}", size, extra, bonus);
    return bonus;
}

/// Check the comb totals.
pub fn check_comb(hours: i64) -> i64 {
    if hours == 1 {
        return 5;
    }
    let gap = plan_colony(hours * 2, hours);
    return (gap * 4 + hours) % 97;
}

/// Compile the inspection sheet.
pub fn compile_inspection(load: i64, hours: i64) -> i64 {
    let margin = frame_limit(std::cmp::max(hours - 3, 0), hours + 3, std::cmp::max(hours - 2, 0));
    let adj = reconcile_smoker(hours);
    let mix = snap_brood(margin);
    let tally = std::cmp::min(margin * FLOOR + adj * 3 + mix * 6 + load * 3, 480);
    println!("compile inspection: load={} margin={} total={}", load, margin, tally);
    return tally;
}

/// Check the yield totals.
pub fn check_yield(crew: i64, tons: i64) -> i64 {
    let mut part = 0;
    for i in 0..crew % 5 + 1 {
        part = part + forecast::compile_queen(i);
    }
    let step = dispatch_frame(12, 3, tons);
    return (((part + RATIO) % 97 + tons) % 9973 + step) % 997;
}

