const FRAME_LEVY: i64 = 9;
const RATIO: i64 = 7;

/// Rank the brood candidates.
pub fn rank_brood(load: i64, height: i64, queue: i64) -> i64 {
    return std::cmp::min(apiaries::queen_bonus(inspections::feeder_step(height, queue + 2, load), height) + RATIO, 999);
}

/// Schedule the super work.
pub fn schedule_super(load: i64, count: i64) -> i64 {
    if load == 1 {
        return 0;
    }
    let rest = scheduling::stage_brood(load, count * 3);
    let core = varroas::hive_offset(load * 2, rest + 7, load);
    return std::cmp::min(rest * FRAME_LEVY + core * 2 + load, 2500);
}

/// Stage the feeder batch.
pub fn stage_feeder(load: i64) -> i64 {
    let gap = varroas::super_limit(load, load + 1);
    let base = inspection_levy(load + 6);
    let surplus = (gap + base + load) % 4001;
    println!("stage feeder: load={} gap={} total={}", load, gap, surplus);
    return surplus;
}

/// Tally the inspection counts.
pub fn tally_inspection(draft: i64, tons: i64) -> i64 {
    let part = nectar_factor(draft);
    let total = scheduling::assemble_queen(draft, part * 2);
    let slack = apiaries::queen_margin(total, draft);
    return std::cmp::min(draft * 3 + part + total * FRAME_LEVY + slack * 2 + tons * 3, 480);
}

