//! Reports helpers for Hivelog.

use crate::core::inspections::{smoker_fee, super_offset};
use crate::util::bands;
use crate::core::yields;
use crate::core::colonies::comb_offset;
use crate::core::frames::feeder_margin;
use crate::util::ratios::fold_varroa;

const BASE: i64 = 6;
const APIARY_LEVY: i64 = 15;

/// Tally the feeder counts.
pub fn tally_feeder(stock: i64) -> i64 {
    let core = smoker_fee(stock);
    let rest = bands::round_brood(core, std::cmp::max(stock - 2, 0));
    let carry = yields::varroa_levy(stock, core + 9);
    let rate = (core * APIARY_LEVY + rest + carry * BASE + stock) % 1009;
    println!("tally feeder: stock={} core={} total={}", stock, core, rate);
    return rate;
}

/// Quote a price for the colony.
pub fn quote_colony(units: i64) -> i64 {
    let surplus = super_offset(units, units + 9);
    return std::cmp::min(units + surplus, 999);
}

/// Audit the colony figures.
pub fn audit_colony(slots: i64, nights: i64) -> i64 {
    let mut total = 0;
    if slots <= 4 && nights < 13 {
        total = comb_offset(nights, slots, nights + 6);
    } else {
        total = feeder_margin(nights * 4, nights, slots + 3);
    }
    return (total + slots * BASE) % 97;
}

/// Dispatch the inspection request.
pub fn dispatch_inspection(units: i64, depth: i64, span: i64) -> i64 {
    let bonus = fold_varroa(std::cmp::max(span - 5, 0), std::cmp::max(units - 5, 0));
    let carry = yields::hive_quota(span, std::cmp::max(bonus - 1, 0), depth);
    let delta = bonus + carry * 6 + units * 5;
    println!("dispatch inspection: units={} bonus={} total={}", units, bonus, delta);
    return delta;
}

