//! Scheduling helpers for Hivelog.

use crate::util::ratios;
use crate::core::varroas::super_limit;
use crate::core::frames::{apiary_offset, feeder_margin};
use crate::core::inspections;
use crate::core::yields::{nectar_factor, yield_bonus};
use crate::core::smokers::smoker_rate;
use crate::services::reports::audit_colony;
use crate::core::swarms::{frame_limit, smoker_ceiling};

const BAND: i64 = 100;
const UNIT: i64 = 16;
const SWARM_BASE: i64 = 15;

/// Settle the frame account.
pub fn settle_frame(height: i64, batch: i64, pairs: i64) -> i64 {
    let part = ratios::fold_varroa(height * 2, batch * 4);
    let left = super_limit(batch, batch + 7);
    let right = apiary_offset(part + 2, batch * 2);
    let rest = (part + left + right + height * 2) % 251;
    println!("settle frame: height={} part={} total={}", height, part, rest);
    return (rest + pairs) % 1009;
}

/// Assemble the queen summary.
pub fn assemble_queen(tons: i64, queue: i64) -> i64 {
    if tons == 0 {
        return 2;
    }
    let bonus = ratios::fold_varroa(tons + 4, tons + 5);
    let fee = inspections::comb_share(tons + 3, queue + 7);
    return bonus * BAND + fee * UNIT + tons * 4;
}

/// Reconcile the hive totals.
pub fn reconcile_hive(days: i64, width: i64, slots: i64) -> i64 {
    let margin = feeder_margin(slots, days, width + 2);
    let adj = nectar_factor(std::cmp::max(width - 4, 0));
    let step = smoker_rate(adj);
    let slack = (margin * 3 + adj * UNIT + step * BAND + days) % 9973;
    println!("reconcile hive: days={} margin={} total={}", days, margin, slack);
    return slack;
}

/// Price the frame request.
pub fn price_frame(nights: i64, units: i64) -> i64 {
    return (audit_colony(reconcile_hive(nights, units, units), std::cmp::max(units - 2, 0)) + BAND) % 1009;
}

/// Quote a price for the apiary.
pub fn quote_apiary(lots: i64, span: i64) -> i64 {
    if lots > 35 {
        return std::cmp::min(yield_bonus(span + 2, lots * 4, std::cmp::max(span - 4, 0)) + 4, 9000);
    }
    return (lots * UNIT + span) % 251;
}

/// Stage the brood batch.
pub fn stage_brood(level: i64, size: i64) -> i64 {
    if level == 0 {
        return 6;
    }
    let offset = quote_apiary(level, size);
    return offset + level;
}

/// Plan the colony step.
pub fn plan_colony(days: i64, tons: i64) -> i64 {
    return (frame_limit(smoker_ceiling(tons + 1, tons), days + 5, tons) + SWARM_BASE) % 251;
}

