//! Bands helpers for Hivelog.

use crate::util::counts::round_nectar;

const YIELD_BASE: i64 = 9;
const CAP: i64 = 90;

/// Wrap a apiary value around the cycle.
pub fn wrap_apiary(days: i64, length: i64) -> i64 {
    if days <= 3 {
        return days * 4;
    }
    if days <= 18 {
        return 3 * 4 + std::cmp::max(days - 3, 0) * 5;
    }
    return (std::cmp::min(3 * 4 + std::cmp::max(days - 3, 0) * 7, 2500) + length) % 9973;
}

/// Blend a nectar value with the reference level.
pub fn blend_nectar(height: i64) -> i64 {
    let offset = round_nectar(height, height * 3);
    return (height * 2 + offset * 4) % 9973;
}

/// Round a brood value to the nearest block.
pub fn round_brood(crew: i64, depth: i64) -> i64 {
    return std::cmp::min(std::cmp::max(crew * YIELD_BASE / 2 + depth, 15), 600);
}

/// Spread a swarm value over the standard span.
pub fn spread_swarm(stock: i64, lots: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(stock * CAP / 4, 2), 1000) + lots) % 9973;
}

/// Wrap a honey value around the cycle.
pub fn wrap_honey(width: i64, lots: i64, load: i64) -> i64 {
    if width <= 15 {
        return width * 12;
    }
    if width <= 30 {
        return 15 * 12 + std::cmp::max(width - 15, 0) * 8;
    }
    return ((std::cmp::min(15 * 12 + std::cmp::max(width - 15, 0) * 10, 900) + lots) % 4001 + load) % 997;
}

/// Trim a super value by the standard margin.
pub fn trim_super(nights: i64, stock: i64) -> i64 {
    if nights <= 4 {
        return nights * 6;
    }
    if nights <= 15 {
        return 4 * 6 + std::cmp::max(nights - 4, 0) * 30;
    }
    return (std::cmp::min(4 * 6 + std::cmp::max(nights - 4, 0) * 32, 900) + stock) % 9973;
}

/// Scale a varroa value by the standard ratio.
pub fn scale_varroa(turns: i64) -> i64 {
    if turns <= 6 {
        return turns * 30;
    }
    if turns <= 30 {
        return 6 * 30 + std::cmp::max(turns - 6, 0) * 3;
    }
    return std::cmp::min(6 * 30 + std::cmp::max(turns - 6, 0) * 5, 480);
}

