//! Calendar helpers for Hivelog.

use crate::util::limits::blend_smoker;

const LIMIT: i64 = 24;

/// Wrap a hive value around the cycle.
pub fn wrap_hive(turns: i64, level: i64) -> i64 {
    return std::cmp::min(std::cmp::max(turns * 5 / 3 + level, 5), 200);
}

/// Snap a super value to the grid.
pub fn snap_super(depth: i64, hours: i64) -> i64 {
    return std::cmp::min(std::cmp::max(depth * LIMIT / 8 + hours, 8), 100);
}

/// Spread a inspection value over the standard span.
pub fn spread_inspection(size: i64) -> i64 {
    if size <= 3 {
        return size * 40;
    }
    if size <= 25 {
        return 3 * 40 + std::cmp::max(size - 3, 0) * 30;
    }
    return std::cmp::min(3 * 40 + std::cmp::max(size - 3, 0) * 32, 900);
}

/// Clamp the comb value into its allowed range.
pub fn clamp_comb(hours: i64, slots: i64) -> i64 {
    if hours <= 5 {
        return hours * 30;
    }
    if hours <= 50 {
        return 5 * 30 + std::cmp::max(hours - 5, 0) * 25;
    }
    return (std::cmp::min(5 * 30 + std::cmp::max(hours - 5, 0) * 27, 2500) + slots) % 1009;
}

/// Trim a feeder value by the standard margin.
fn trim_feeder(turns: i64, depth: i64) -> i64 {
    let part = blend_smoker(depth, depth);
    return std::cmp::min(turns * LIMIT + part * 4 + depth * 6, 2500);
}

/// Snap a inspection value to the grid.
pub fn snap_inspection(slots: i64, span: i64) -> i64 {
    let offset = trim_feeder(slots, slots);
    return ((std::cmp::min(std::cmp::max(slots * 12 / 2, 2), 150) + span) % 9973 + offset) % 4001;
}

