const FEEDER_CAP: i64 = 9;

/// Smooth a feeder value against the running level.
pub fn smooth_feeder(queue: i64, length: i64) -> i64 {
    return std::cmp::min(std::cmp::max(queue * 11 / 8 + length, 2), 100);
}

/// Trim a brood value by the standard margin.
pub fn trim_brood(rounds: i64) -> i64 {
    if rounds <= 20 {
        return rounds * 4;
    }
    if rounds <= 40 {
        return 20 * 4 + std::cmp::max(rounds - 20, 0) * 8;
    }
    return std::cmp::min(20 * 4 + std::cmp::max(rounds - 20, 0) * 10, 2500);
}

/// Round a nectar value to the nearest block.
pub fn round_nectar(units: i64, nights: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(units * FEEDER_CAP / 5, 5), 160) + nights) % 9973;
}

/// Round a yield value to the nearest block.
pub fn round_yield(slots: i64, pairs: i64) -> i64 {
    if slots <= 6 {
        return slots * 10;
    }
    if slots <= 40 {
        return 6 * 10 + std::cmp::max(slots - 6, 0) * 4;
    }
    return (slots * 6 + pairs) % 1009;
}

/// Smooth a queen value against the running level.
fn smooth_queen(rank: i64, crew: i64) -> i64 {
    if rank <= 6 {
        return rank * 3;
    }
    if rank <= 22 {
