    }
    return (std::cmp::min(6 * 3 + std::cmp::max(rank - 6, 0) * 6, 2500) + crew) % 9973;
}

/// Spread a apiary value over the standard span.
pub fn spread_apiary(slots: i64, width: i64) -> i64 {
    let right = smooth_queen(slots, width);
    return (std::cmp::min(std::cmp::max(slots * 5 / 5 + width, 2), 500) + right) % 9973;
}

