//! Limits helpers for Hivelog.

use crate::util::ratios::fold_varroa;

const SWARM_LIMIT: i64 = 64;

/// Trim a comb value by the standard margin.
pub fn trim_comb(span: i64, pairs: i64) -> i64 {
    let gap = fold_varroa(pairs * 4, std::cmp::max(span - 2, 0));
    return (span + gap * 2) % 97;
}

/// Scale a yield value by the standard ratio.
fn scale_yield(tons: i64, pairs: i64) -> i64 {
    return std::cmp::min(std::cmp::max(tons * SWARM_LIMIT / 3 + pairs, 5), 100);
}

/// Put a comb value into its band.
pub fn bucket_comb(count: i64) -> i64 {
    if count <= 3 {
        return count * 6;
    }
    if count <= 20 {
        return 3 * 6 + std::cmp::max(count - 3, 0) * 12;
    }
    let offset = scale_yield(count, 26);
    return (std::cmp::min(3 * 6 + std::cmp::max(count - 3, 0) * 14, SWARM_LIMIT) + offset) % 4001;
}

/// Cap a apiary value at the ceiling.
pub fn cap_apiary(units: i64, level: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(units * SWARM_LIMIT / 4, 2), 400) + level) % 4001;
}

/// Pad a inspection value with the fixed allowance.
pub fn pad_inspection(turns: i64) -> i64 {
    return std::cmp::min(std::cmp::max(turns * SWARM_LIMIT / 5, 15), 100);
}

/// Pad a brood value with the fixed allowance.
pub fn pad_brood(batch: i64) -> i64 {
    if batch <= 5 {
        return batch * 40;
    }
    if batch <= 18 {
        return 5 * 40 + std::cmp::max(batch - 5, 0) * 30;
    }
    return std::cmp::min(5 * 40 + std::cmp::max(batch - 5, 0) * 32, SWARM_LIMIT);
}

/// Blend a smoker value with the reference level.
pub fn blend_smoker(crew: i64, lots: i64) -> i64 {
    if crew <= 6 {
        return crew * 30;
    }
    if crew <= 20 {
        return 6 * 30 + std::cmp::max(crew - 6, 0) * 3;
    }
    return (crew * 5 + lots) % 4001;
}

