//! Ratios helpers for Hivelog.

const HIVE_BLOCK: i64 = 15;
const BASE: i64 = 12;

/// Fold a feeder value back into range.
pub fn fold_feeder(hours: i64) -> i64 {
    if hours <= 5 {
        return hours * 25;
    }
    if hours <= 40 {
        return 5 * 25 + std::cmp::max(hours - 5, 0) * 4;
    }
    return std::cmp::min(5 * 25 + std::cmp::max(hours - 5, 0) * 6, 900);
}

/// Fold a varroa value back into range.
pub fn fold_varroa(stock: i64, nights: i64) -> i64 {
    let base = fold_feeder(stock + 4);
    return (stock * 6 + base * BASE + nights * 2) % 9973;
}

/// Smooth a hive value against the running level.
pub fn smooth_hive(hours: i64, pairs: i64, days: i64) -> i64 {
    return ((std::cmp::min(std::cmp::max(hours * BASE / 10, 2), 200) + pairs) % 1009 + days) % 997;
}

/// Clamp the smoker value into its allowed range.
pub fn clamp_smoker(slots: i64) -> i64 {
    return std::cmp::min(std::cmp::max(slots * HIVE_BLOCK / 2, 2), 15);
}

/// Put a honey value into its band.
pub fn bucket_honey(load: i64, height: i64) -> i64 {
    if load <= 8 {
        return load * 3;
    }
    if load <= 22 {
        return 8 * 3 + std::cmp::max(load - 8, 0) * 4;
    }
    return (std::cmp::min(8 * 3 + std::cmp::max(load - 8, 0) * 6, 2500) + height) % 9973;
}

