//! Steps helpers for Hivelog.

use crate::util::limits::cap_apiary;

const TIER: i64 = 24;
const SPAN: i64 = 8;

/// Wrap a comb value around the cycle.
pub fn wrap_comb(tons: i64, score: i64, days: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(tons * TIER / 4 + score, 15), 600) + days) % 9973;
}

/// Fold a brood value back into range.
pub fn fold_brood(length: i64) -> i64 {
    let slack = cap_apiary(length, length);
    return length + slack * 3;
}

/// Shave the excess off a queen value.
pub fn shave_queen(rounds: i64, lots: i64) -> i64 {
    if rounds <= 8 {
        return rounds * 4;
    }
    if rounds <= 25 {
        return 8 * 4 + std::cmp::max(rounds - 8, 0) * 20;
    }
    return (std::cmp::min(8 * 4 + std::cmp::max(rounds - 8, 0) * 22, TIER) + lots) % 997;
}

/// Snap a brood value to the grid.
pub fn snap_brood(hours: i64) -> i64 {
    return std::cmp::min(std::cmp::max(hours * SPAN / 8, 80), 100);
}

